initJs:
function(container, apiUrl, tables) {
  // サンプルチェック結果データ
  const sampleCheckResults = [
    {
      id: 'check-1',
      type: 'error',
      category: '必須項目',
      message: '作業員IDが入力されていません',
      targetValue: '',
      field: 'worker_id'
    },
    {
      id: 'check-2', 
      type: 'error',
      category: '日時整合性',
      message: '終了時刻が開始時刻より前になっています',
      targetValue: '08:00 > 18:00',
      field: 'work_time'
    },
    {
      id: 'check-3',
      type: 'error', 
      category: '入力形式',
      message: 'プロジェクト名に使用できない文字が含まれています',
      targetValue: 'プロジェクト@#$',
      field: 'project_name'
    },
    {
      id: 'check-4',
      type: 'warning',
      category: '作業時間妥当性',
      message: '作業時間が12時間を超過しています',
      targetValue: '12:30',
      field: 'work_duration'
    },
    {
      id: 'check-5',
      type: 'warning',
      category: '重複データ',
      message: '同じ時間帯の作業記録が既に存在します',
      targetValue: '2024-01-15 09:00',
      field: 'work_start_time'
    },
    {
      id: 'check-6',
      type: 'info',
      category: '入力形式',
      message: '作業内容の文字数が推奨範囲を下回っています',
      targetValue: '点検作業',
      field: 'work_content'
    }
  ];

  let currentCheckResults = [...sampleCheckResults];

  // チェック結果テーブル再描画
  function renderCheckResults(results) {
    const tbody = container.querySelector('#check-results-tbody');
    tbody.innerHTML = results.map(result => {
      const typeIcon = result.type === 'error' ? '❌' : result.type === 'warning' ? '⚠️' : 'ℹ️';
      const typeColor = result.type === 'error' ? '#dc2626' : result.type === 'warning' ? '#ffa500' : '#3b82f6';

      return `
        <tr data-id="${result.id}">
          <td style="text-align: center;">
            <span style="color: ${typeColor};">${typeIcon}</span>
          </td>
          <td style="font-size: 12px; color: var(--text);">${result.category}</td>
          <td style="font-size: 12px; color: var(--text);">${result.message}</td>
          <td style="font-size: 12px; color: var(--text-muted);">${result.targetValue}</td>
          <td>
            <button class="action-btn secondary fix-btn" data-id="${result.id}" style="font-size: 11px; padding: 3px 6px;">
              修正
            </button>
          </td>
        </tr>
      `;
    }).join('');

    updateSummary(results);
  }

  // サマリー更新
  function updateSummary(results) {
    const errorCount = results.filter(r => r.type === 'error').length;
    const warningCount = results.filter(r => r.type === 'warning').length;

    container.querySelector('#error-count').textContent = errorCount;
    container.querySelector('#warning-count').textContent = warningCount;

    const statusIcon = container.querySelector('#status-icon');
    const statusText = container.querySelector('#status-text');
    const saveStatus = container.querySelector('#save-status');

    if (errorCount > 0) {
      statusIcon.textContent = '❌';
      statusText.textContent = 'エラーあり';
      statusText.style.color = '#dc2626';
      saveStatus.textContent = '不可';
      saveStatus.style.color = '#dc2626';
    } else if (warningCount > 0) {
      statusIcon.textContent = '⚠️';
      statusText.textContent = '警告あり';
      statusText.style.color = '#ffa500';
      saveStatus.textContent = '可能';
      saveStatus.style.color = '#10b981';
    } else {
      statusIcon.textContent = '✅';
      statusText.textContent = 'OK';
      statusText.style.color = '#10b981';
      saveStatus.textContent = '可能';
      saveStatus.style.color = '#10b981';
    }
  }

  // フィルタリング
  function applyFilters() {
    const typeFilter = container.querySelector('#filter-type').value;
    const keyword = container.querySelector('#filter-keyword').value.toLowerCase();

    let filtered = currentCheckResults;

    if (typeFilter) {
      filtered = filtered.filter(r => r.type === typeFilter);
    }

    if (keyword) {
      filtered = filtered.filter(r => 
        r.message.toLowerCase().includes(keyword) ||
        r.category.toLowerCase().includes(keyword) ||
        r.targetValue.toLowerCase().includes(keyword)
      );
    }

    renderCheckResults(filtered);
  }

  // 修正提案適用
  window.applySuggestion = function(field, value) {
    alert(`${field} を ${value} に修正しました`);
    // 実際の修正処理をここに実装
    window.showScreen('scr-1778907319067'); // 修正入力画面へ
  };

  // 初期描画
  renderCheckResults(currentCheckResults);

  // イベントリスナー
  container.querySelector('#filter-type').addEventListener('change', applyFilters);
  container.querySelector('#filter-keyword').addEventListener('input', applyFilters);

  container.querySelector('#btn-refresh').addEventListener('click', async () => {
    // 最新のチェック結果を取得（実際はAPIから）
    renderCheckResults(currentCheckResults);
  });

  container.querySelector('#btn-clear-all').addEventListener('click', () => {
    if (confirm('全てのチェック結果をクリアしますか？')) {
      currentCheckResults = [];
      renderCheckResults(currentCheckResults);
    }
  });

  container.querySelector('#btn-export-log').addEventListener('click', () => {
    const csvContent = '\uFEFF' + [
      'チェック種別,項目,メッセージ,対象値',
      ...currentCheckResults.map(r => `${r.type},${r.category},"${r.message}",${r.targetValue}`)
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'check_results.csv';
    a.click();
    URL.revokeObjectURL(url);
  });

  container.querySelector('#btn-fix-errors').addEventListener('click', () => {
    window.showScreen('scr-1778907319067'); // 修正入力画面
  });

  container.querySelector('#btn-view-details').addEventListener('click', () => {
    window.showScreen('scr-1778907226171'); // 記録確認画面
  });

  container.querySelector('#btn-emergency-report').addEventListener('click', () => {
    window.showScreen('scr-1778907330826'); // 緊急報告画面
  });

  // 行レベル操作
  container.addEventListener('click', (e) => {
    const fixBtn = e.target.closest('.fix-btn');
    if (fixBtn) {
      const checkId = fixBtn.dataset.id;
      const checkResult = currentCheckResults.find(r => r.id === checkId);
      if (checkResult) {
        window.showScreen('scr-1778907319067'); // 修正入力画面
      }
    }
  });
}
